insert into public.software (name, slug, tagline, description_short, description_full, logo_url, category_id, starting_price, price_currency, billing_period, price_is_net, price_unit, free_trial, trial_days, free_version, free_demo, pricing_plans, pricing_note, features, top_features, integrations, pros, cons, ideal_for, brand_color, gobd_compliant, datev_interface, e_invoicing, elster_submission, hosting_location, dpa_available, iso27001, tse_certified, skr_support, german_support, vendor_country, compliance_checked_at, affiliate_url, vendor_website, affiliate_network, vendor_name, founded_year, vendor_hq, support_types, countries_available, languages, editorial_rating, editorial_ease, editorial_value, editorial_service, editorial_functionality, editorial_verdict, editorial_review, editorial_author, editorial_tested_at, status, featured) values
('DATEV Unternehmen online', 'datev-unternehmen-online', 'Die Belegdrehscheibe zwischen Unternehmen und Steuerkanzlei', 'Belege digitalisieren, Zahlungen vorbereiten und Auswertungen abrufen, direkt verbunden mit der Buchhaltung Ihrer DATEV-Kanzlei.', '<p>DATEV Unternehmen online ist die Cloud-Plattform der Nürnberger Genossenschaft DATEV eG für die Zusammenarbeit zwischen Unternehmen und Steuerkanzlei. Belege werden per App, Scanner oder Upload erfasst, revisionssicher im DATEV-Rechenzentrum archiviert und stehen der Kanzlei unmittelbar für die Finanzbuchhaltung zur Verfügung.</p><p>Die DATEV eG zählt rund 40.000 Mitglieder, überwiegend Steuerkanzleien. Für viele Mittelständler ist Unternehmen online deshalb nicht eine Option unter vielen, sondern der Standard, den die Kanzlei vorgibt. Die Lizenz wird in der Regel über die Kanzlei bereitgestellt und pro Mandant abgerechnet.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), null, 'EUR', 'month', true, 'client', false, null, false, true, '[]'::jsonb, 'Lizenz in der Regel über die Steuerkanzlei', '["Belegerfassung per OCR","Bankanbindung","E-Rechnung (XRechnung/ZUGFeRD)","DATEV-Export","Kassenbuch","Anlagenverwaltung","Bilanz & GuV","EÜR","UStVA per ELSTER","SEPA-Lastschrift","Mobile App"]'::jsonb, '["Direkte Verbindung zur DATEV-Kanzlei","Revisionssicheres Belegarchiv im DATEV-Rechenzentrum","Zahlungsverkehr mit Belegbezug","Betriebswirtschaftliche Auswertungen (BWA)"]'::jsonb, '["DATEV Kanzlei-Rechnungswesen","DATEV Lohn und Gehalt","Candis","Lexware Office","sevdesk","Shopify","PayPal"]'::jsonb, '["Nahtlose Zusammenarbeit mit der Steuerkanzlei","Höchste Akzeptanz bei Steuerberatern","Rechenzentrum in Deutschland"]'::jsonb, '["Oberfläche wirkt teils altmodisch","Einrichtung und Lizenz meist nur über die Kanzlei","Preise nicht öffentlich"]'::jsonb, 'Unternehmen, deren Steuerkanzlei die Buchhaltung mit DATEV führt.', null, 'ja', 'vollintegriert', '["XRechnung","ZUGFeRD"]'::jsonb, true, 'Deutschland', true, true, null, '["SKR03","SKR04"]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.datev.de/unternehmen-online', 'keins', 'DATEV eG', 1966, 'Nürnberg', '["Über die Steuerkanzlei","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.3, 3.7, 4, 4.2, 4.6, 'Wenn Ihre Steuerkanzlei mit DATEV bucht, führt an Unternehmen online kaum ein Weg vorbei. Die Oberfläche ist nicht die modernste, aber kein anderes Programm bringt Belege, Zahlungsverkehr und Kanzlei so reibungslos zusammen.', '<h3>Wofür das Programm gedacht ist</h3><p>DATEV Unternehmen online ist keine Buchhaltungssoftware im klassischen Sinn, sondern die Brücke zwischen Ihrem Betrieb und der Kanzlei. Sie erfassen Belege, bezahlen Rechnungen und sehen Auswertungen. Gebucht wird in der Regel weiterhin in der Kanzlei, nur eben ohne Pendelordner und ohne Nachfragen per E-Mail.</p><p>Das ist der entscheidende Unterschied zu Lexware Office oder sevdesk. Dort machen Sie die Buchhaltung selbst und exportieren am Ende. Hier bleibt die Arbeitsteilung mit der Steuerberatung erhalten, nur der Weg der Unterlagen wird digital.</p><h3>Was im Alltag überzeugt</h3><p>Belege lassen sich per App fotografieren, per Scanner hochladen oder per E-Mail einsenden. Sie landen im DATEV-Rechenzentrum in Nürnberg und sind dort für die Kanzlei sofort sichtbar. Bei Rückfragen muss niemand suchen, weil Beleg, Buchung und Zahlung miteinander verknüpft sind.</p><p>Stark ist der Zahlungsverkehr. Eingangsrechnungen werden direkt aus dem Belegbild heraus zur Überweisung vorbereitet, und die Zahlung ist später in der Buchung sichtbar. Die betriebswirtschaftliche Auswertung steht zur Verfügung, sobald die Kanzlei den Monat abgeschlossen hat.</p><h3>Wo es hakt</h3><p>Die Bedienung wirkt stellenweise wie aus einer anderen Zeit. Menüs sind tief verschachtelt, und wer vorher mit einem modernen Cloud-Tool gearbeitet hat, braucht etwas Geduld. Außerdem können Sie das Programm nicht einfach selbst abonnieren. Die Lizenz wird fast immer über die Kanzlei freigeschaltet und abgerechnet.</p><h3>Kosten und Zielgruppe</h3><p>DATEV veröffentlicht keine Endkundenpreise, weil die Kanzlei die Lizenz pro Mandant bereitstellt und oft mit dem eigenen Honorar bündelt. Fragen Sie deshalb direkt bei Ihrer Steuerberatung nach. Das Programm lohnt sich für jedes Unternehmen, dessen Kanzlei mit DATEV arbeitet, und das sind in Deutschland die allermeisten.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('Lexware Office', 'lexware-office', 'Buchhaltung, Rechnungen und Banking für Selbstständige und kleine Unternehmen', 'Cloud-Buchhaltung mit Rechnungsstellung, Belegerfassung, UStVA per ELSTER und DATEV-Export, besonders einfach zu bedienen.', '<p>Lexware Office (vormals lexoffice) ist die Cloud-Buchhaltung von Haufe-Lexware aus Freiburg. Die Software deckt Angebote, Rechnungen, Belegerfassung und Bankabgleich ab und übermittelt die Umsatzsteuer-Voranmeldung direkt per ELSTER an das Finanzamt. Ab Paket L kommen EÜR, Anlagenverwaltung und das Kassenbuch hinzu.</p><p>Für die Zusammenarbeit mit der Steuerkanzlei steht ein DATEV-Export sowie ein kostenloser Steuerberater-Zugang bereit. Die Daten liegen in Rechenzentren in Deutschland; ein Auftragsverarbeitungsvertrag nach Art. 28 DSGVO ist im Kundenkonto abrufbar.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 7.9, 'EUR', 'month', true, 'account', true, 30, false, false, '[{"name":"S","price":7.9,"period":"month","unit":"account","features":["Belegerfassung und GoBD-Belegarchiv","E-Rechnungen empfangen","App mit Belegscanner"]},{"name":"M","price":12.9,"period":"month","unit":"account","features":["Alles aus S","Angebote, E-Rechnungen und Mahnungen"]},{"name":"L","price":21.9,"period":"month","unit":"account","features":["Alles aus M","Buchhaltung, EÜR und Umsatzsteuer","UStVA und Zusammenfassende Meldung","BWA, GuV, Kassenbuch"],"highlighted":true},{"name":"XL","price":32.9,"period":"month","unit":"account","features":["Alles aus L","EU- und Abschlagsrechnungen","Public API"]}]'::jsonb, null, '["Rechnungen & Angebote","E-Rechnung (XRechnung/ZUGFeRD)","Belegerfassung per OCR","Bankanbindung","UStVA per ELSTER","EÜR","DATEV-Export","Mahnwesen","Kassenbuch","Anlagenverwaltung","Mobile App"]'::jsonb, '["UStVA direkt per ELSTER","Automatischer Bankabgleich","Kostenloser Steuerberater-Zugang","E-Rechnung im Ein- und Ausgang"]'::jsonb, '["DATEV","PayPal","Shopify","WooCommerce","Stripe","Zapier","Personio"]'::jsonb, '["Sehr einfache Bedienung","Günstiger Einstieg","UStVA mit wenigen Klicks"]'::jsonb, '["Bilanzierung nur eingeschränkt","Kaum Anpassungsmöglichkeiten bei Rechnungsvorlagen","Telefon-Support nicht in allen Paketen"]'::jsonb, 'Selbstständige, Freiberufler und kleine Unternehmen mit EÜR.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, true, 'Deutschland', true, null, null, '["SKR03","SKR04"]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.lexware.de/', 'direkt', 'Haufe-Lexware GmbH & Co. KG', 1989, 'Freiburg im Breisgau', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.5, 4.7, 4.4, 4.2, 4.3, 'Lexware Office ist das zugänglichste Buchhaltungsprogramm für Selbstständige und kleine Firmen. Wer die Umsatzsteuer selbst meldet und eine EÜR macht, ist mit dem Tarif L für 21,90 € gut versorgt.', '<h3>Der erste Eindruck</h3><p>Das frühere lexoffice aus Freiburg hat sich seinen Ruf mit einer Oberfläche erarbeitet, die Buchhaltung weniger nach Buchhaltung aussehen lässt. Rechnungen schreiben, Belege fotografieren, Bankumsätze zuordnen: Die Wege sind kurz, und Fachbegriffe tauchen erst auf, wenn sie wirklich gebraucht werden.</p><h3>Die Tarife genau gelesen</h3><p>Hier sollten Sie aufpassen, denn die Namen verraten wenig. Der Tarif S für 7,90 € deckt nur die Belegerfassung mit Archiv ab. Rechnungen und Mahnungen kommen erst mit M für 12,90 €. Die eigentliche Buchhaltung mit EÜR, Umsatzsteuer-Voranmeldung, BWA und Kassenbuch gibt es ab L für 21,90 €. XL für 32,90 € ergänzt Abschlags- und EU-Rechnungen sowie eine API.</p><p>Für die meisten Selbstständigen ist also L der richtige Tarif. Die Preise sind netto und monatlich kündbar, zum Start gibt es regelmäßig Rabatte für die ersten Monate.</p><h3>Stärken im Alltag</h3><p>Der Bankabgleich schlägt passende Belege zuverlässig vor, und die Umsatzsteuer-Voranmeldung geht direkt aus dem Programm an ELSTER. Die Steuerkanzlei erhält einen eigenen Zugang oder einen Export im DATEV-Format. E-Rechnungen im XRechnung- und ZUGFeRD-Format können Sie empfangen und erstellen, womit die Pflicht seit 2025 abgedeckt ist.</p><h3>Grenzen</h3><p>Für bilanzierende GmbHs mit komplexeren Abschlüssen stößt Lexware Office an Grenzen, auch wenn XL mehr kann als früher. Wer eine Lagerverwaltung braucht, muss zu einem anderen Produkt greifen. Die 30 Tage kostenlose Testphase umfasst alle Funktionen und reicht, um einen vollen Monat abzuschließen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('sevdesk', 'sevdesk', 'Rechnungen und Buchhaltung für Selbstständige und kleine Unternehmen', 'Rechnungsprogramm und Buchhaltung aus Offenburg: GoBD-konform, mit DATEV-Export, E-Rechnung und deutschem Serverstandort.', '<p>sevdesk ist eine Cloud-Buchhaltung aus Offenburg, die sich an Selbstständige, Freiberufler und kleine Unternehmen richtet. Die Software verbindet Rechnungsstellung, automatische Belegerkennung, Bankanbindung und Umsatzsteuer-Voranmeldung in einer Oberfläche.</p><p>Im Tarif Buchhaltung Pro kommen Kostenstellen, eine REST-API und die BWA in Echtzeit hinzu. Buchungen und Belege lassen sich im DATEV-Format an die Steuerkanzlei übergeben; E-Rechnungen im Format XRechnung und ZUGFeRD werden empfangen und ausgestellt.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 0, 'EUR', 'month', true, 'account', true, null, true, false, '[{"name":"Kostenlos","price":0,"period":"month","unit":"account","features":["3 Rechnungen pro Monat","Unbegrenzt Kontakte und Produkte"]},{"name":"Rechnung","price":11.9,"period":"month","unit":"account","features":["Unbegrenzt Rechnungen und Angebote","Mahnungen","Steuerberater-Zugang"]},{"name":"Buchhaltung","price":25.9,"period":"month","unit":"account","features":["KI-Belegerfassung","Bankanbindung","EÜR und GuV","UStVA per ELSTER"],"highlighted":true},{"name":"Buchhaltung Pro","price":34.9,"period":"month","unit":"account","features":["Alles aus Buchhaltung","Kostenstellen","REST-API","BWA in Echtzeit"]}]'::jsonb, 'Buchhaltungstarife ab 22,90 € bei jährlicher Zahlung', '["Rechnungen & Angebote","E-Rechnung (XRechnung/ZUGFeRD)","Belegerfassung per OCR","Bankanbindung","UStVA per ELSTER","EÜR","DATEV-Export","Mahnwesen","Kassenbuch","SEPA-Lastschrift","Mobile App"]'::jsonb, '["Automatische Belegerkennung","E-Rechnung XRechnung + ZUGFeRD","DATEV-Export für die Kanzlei","Dauerhaft kostenloser Einstiegstarif"]'::jsonb, '["DATEV","Shopify","Amazon","eBay","PayPal","Stripe","Zapier"]'::jsonb, '["Übersichtliche Oberfläche","Gute Belegerkennung","Kostenloser Einstieg möglich"]'::jsonb, '["Preise steigen mit Funktionsumfang deutlich","Keine Bilanzierung","Support zeitweise langsam"]'::jsonb, 'Freiberufler und kleine Unternehmen, die Rechnungen und Buchhaltung selbst erledigen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, true, 'Deutschland', true, null, null, '["SKR03","SKR04"]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://sevdesk.de/', 'direkt', 'sevdesk GmbH', 2013, 'Offenburg', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.4, 4.5, 4.3, 4.1, 4.4, 'sevdesk ist die stärkste Alternative zu Lexware Office, mit besserer Belegerkennung und einem kostenlosen Einstieg. Für die eigentliche Buchhaltung brauchen Sie den Tarif Buchhaltung ab 22,90 € bei jährlicher Zahlung.', '<h3>Worum es geht</h3><p>Die Software aus Offenburg richtet sich an Selbstständige, Freiberufler und kleine Firmen, die Rechnungen schreiben und ihre Buchhaltung selbst vorbereiten. Das Programm ist vollständig in der Cloud, eine App für Belege gehört dazu.</p><h3>Was sevdesk besonders gut kann</h3><p>Die KI-gestützte Belegerfassung liest Betrag, Datum, Lieferant und Steuersatz meist korrekt aus und schlägt eine passende Buchung vor. Wer viele kleine Belege hat, etwa Tankquittungen oder Onlinekäufe, spart hier spürbar Zeit. Die Umsatzsteuer-Voranmeldung wird direkt übermittelt, Einnahmenüberschussrechnung und GuV entstehen laufend.</p><p>Für die Zusammenarbeit mit der Kanzlei gibt es einen Steuerberater-Zugang und den DATEV-Export. Im Tarif Buchhaltung Pro kommen Kostenstellen, eine REST-API und die BWA in Echtzeit dazu.</p><h3>Preise</h3><p>sevdesk hat inzwischen einen dauerhaft kostenlosen Tarif mit drei Rechnungen im Monat. Das reicht zum Ausprobieren, nicht für den Betrieb. Der Tarif Rechnung kostet 11,90 € monatlich, Buchhaltung 25,90 € und Buchhaltung Pro 34,90 €. Bei jährlicher oder zweijähriger Zahlung sinken die Preise deutlich, bei Buchhaltung auf 22,90 € beziehungsweise 19,90 €.</p><h3>Für wen es passt</h3><p>sevdesk lohnt sich für alle, die ihre Buchhaltung selbst im Griff haben wollen und viele Belege verarbeiten. Wer vor allem Wert auf eine möglichst einfache Oberfläche legt, sollte Lexware Office daneben testen. Beide Programme lassen sich kostenlos ausprobieren.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true),
('Sage Active', 'sage-active', 'Cloud-Buchhaltung für kleine und mittlere Unternehmen', 'Doppelte Buchführung in der Cloud mit Rechnungswesen, Bankabgleich sowie im Tarif Essentials auch Lohn und HR.', '<p>Sage Active ist die Cloud-Buchhaltung der Sage GmbH für kleine und mittlere Unternehmen in Deutschland. Sie unterstützt die doppelte Buchführung nach HGB, Umsatzsteuer-Voranmeldungen und die Übergabe an die Steuerkanzlei.</p><p>Im Tarif Essentials sind zusätzlich Lohnabrechnung und HR-Funktionen enthalten. Sage Active eignet sich für Unternehmen, die über die EÜR hinausgewachsen sind und bilanzieren müssen, ohne eine lokale Installation betreiben zu wollen.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 25, 'EUR', 'month', true, 'account', true, 30, false, true, '[{"name":"Starter","price":25,"period":"month","unit":"account","features":["1 Unternehmen, 5 Nutzer","Angebote und Rechnungen","KI-Belegerfassung inkl. E-Rechnung","Bankabgleich","Sage Copilot"]},{"name":"Essentials","price":49,"period":"month","unit":"account","features":["10 Nutzer, 2 Mitarbeitende in der Lohnabrechnung","Doppelte Buchführung SKR03/SKR04","EÜR, Bilanz, GuV","UStVA per ELSTER","Lohnabrechnung und HR"],"highlighted":true}]'::jsonb, null, '["Rechnungen & Angebote","E-Rechnung (XRechnung/ZUGFeRD)","Belegerfassung per OCR","Bankanbindung","UStVA per ELSTER","Bilanz & GuV","DATEV-Export","Mahnwesen","Anlagenverwaltung"]'::jsonb, '["Doppelte Buchführung nach HGB","Lohn & HR im Tarif Essentials","Cloud ohne lokale Installation"]'::jsonb, '["DATEV","Microsoft 365","PayPal","Sage HR Suite"]'::jsonb, '["Bilanzierung in der Cloud","Lohn im selben System möglich","Etablierter Anbieter"]'::jsonb, '["Kleineres Ökosystem an Erweiterungen als bei den Marktführern","Lohnabrechnung im Paket auf zwei Mitarbeitende begrenzt"]'::jsonb, 'Bilanzierende kleine und mittlere Unternehmen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, true, 'EU', true, null, null, '["SKR03","SKR04"]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.sage.com/de-de/produkte/sage-active/', 'keins', 'Sage GmbH', null, 'Frankfurt am Main', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.3, 4.4, 4.3, 4.3, 4.3, 'Sage Active ist die modernste Buchhaltung im Sage-Programm und eine der wenigen Cloud-Lösungen dieser Preisklasse, in der die Lohnabrechnung schon im Paket steckt. Mit 49 € für Essentials ist sie für kleine Firmen mit ein oder zwei Angestellten ein ernsthafter Kandidat.', '<h3>Was Sage Active von anderen unterscheidet</h3><p>Die meisten Cloud-Buchhaltungen hören beim Lohn auf. Sage Active nicht: Im Tarif Essentials sind doppelte Buchführung nach SKR03 oder SKR04, Anlagenbuchhaltung, EÜR, Bilanz, Umsatzsteuer-Voranmeldung und die Lohnabrechnung für zwei Mitarbeitende enthalten. Dazu kommen zehn Nutzer. Für einen kleinen Betrieb mit einer Bürokraft und einem Gesellen ist das eine runde Sache.</p><p>Der Einstieg Starter für 25 € richtet sich an alle, die zunächst nur Angebote und Rechnungen schreiben wollen, mit fünf Nutzern und einem Überblick über offene Posten.</p><h3>Im Alltag</h3><p>Eingangsrechnungen und Belege lassen sich als Bild, PDF oder E-Rechnung hochladen, die KI liest sie aus und ordnet sie zu. Aus Ausgangsrechnungen und Bankumsätzen entstehen Buchungen automatisch. Der Wechsel von Ist- auf Sollversteuerung ist ohne Umwege möglich, was bei wachsenden Firmen gelegentlich nötig wird.</p><p>Der neue Sage Copilot fasst überfällige Rechnungen zusammen und formuliert Zahlungserinnerungen. Das ist kein Muss, aber eine angenehme Hilfe bei der wöchentlichen Kontrolle. Für die Kanzlei gibt es den Export im DATEV-Format.</p><h3>Wo Sage Active noch aufholt</h3><p>Das Ökosystem an Erweiterungen ist kleiner als bei Lexware oder sevdesk, auch wenn es mit clockin, Shopware und Forderungsmanagement bereits sinnvolle Partner gibt. Wer sehr viele Mitarbeitende abrechnet, stößt irgendwann an die Grenzen des Pakets und sollte sich Sage HR & Payroll ansehen.</p><h3>Kosten und Test</h3><p>Starter kostet 25 €, Essentials 49 € im Monat netto. Beide Tarife lassen sich 30 Tage kostenlos testen. Sage bietet für Neukunden zeitweise Rabatte auf die ersten Monate an, danach gilt der Listenpreis. Wer eine persönliche Einschätzung möchte, kann einen kostenlosen Beratungstermin buchen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Sage 50 Connected', 'sage-50-connected', 'Warenwirtschaft und Finanzbuchhaltung für den Mittelstand', 'Lokal installierte Kombination aus Finanzbuchhaltung und Warenwirtschaft mit ZUGFeRD-Ausgangsrechnungen.', '<p>Sage 50 Connected ist die lokal installierte Lösung von Sage für Finanzbuchhaltung und Warenwirtschaft. Sie richtet sich an kleine und mittlere Unternehmen, die Aufträge, Lager und Buchhaltung in einem System führen möchten.</p><p>Abgerechnet wird als Abonnement je Arbeitsplatz; über Connected-Dienste lassen sich Belege und Banking in die Cloud erweitern. Ausgangsrechnungen können im ZUGFeRD-Format erzeugt werden.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 30, 'EUR', 'month', true, 'user', true, 30, false, true, '[{"name":"Standard","price":30,"period":"month","unit":"user","features":["Angebote und Rechnungen","Integriertes Onlinebanking","Warenwirtschaft","Digitale Belegarchivierung","EÜR oder Bilanz","DATEV-Schnittstelle, E-Rechnung"]},{"name":"Comfort","price":35,"period":"month","unit":"user","features":["Alles aus Standard","Anlagenbuchhaltung","Bestellwesen","ab 2 Arbeitsplätzen"],"highlighted":true},{"name":"Professional","price":40,"period":"month","unit":"user","features":["Alles aus Comfort","Erweiterte Warenwirtschaft","ab 3 Arbeitsplätzen"]}]'::jsonb, 'pro Arbeitsplatz', '["Rechnungen & Angebote","E-Rechnung (XRechnung/ZUGFeRD)","Bankanbindung","UStVA per ELSTER","Bilanz & GuV","DATEV-Export","Mahnwesen","Kassenbuch","Anlagenverwaltung","SEPA-Lastschrift"]'::jsonb, '["FiBu und Warenwirtschaft in einem","Lokale Datenhaltung","ZUGFeRD-Ausgangsrechnungen"]'::jsonb, '["DATEV","Microsoft Office","Shopware"]'::jsonb, '["Großer Funktionsumfang","Daten bleiben im eigenen Haus","Warenwirtschaft integriert"]'::jsonb, '["Installation und Updates nötig","Einarbeitung braucht einige Tage"]'::jsonb, 'Händler und Dienstleister mit eigener IT, die FiBu und Warenwirtschaft kombinieren.', null, 'ja', 'export', '["ZUGFeRD"]'::jsonb, true, 'on-premise', null, null, null, '["SKR03","SKR04"]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.sage.com/de-de/produkte/sage-50connected/', 'keins', 'Sage GmbH', null, 'Frankfurt am Main', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 3.9, 4.1, 4.2, 4.6, 'Sage 50 ist die richtige Wahl für kleine Unternehmen, die Buchhaltung, Auftragsbearbeitung und Warenwirtschaft in einem Programm wollen und lieber mit einer installierten Software arbeiten. Kaum ein Cloud-Tool dieser Preisklasse bietet so viel Tiefe.', '<h3>Das Konzept</h3><p>Sage 50 ist der Klassiker im Sage-Sortiment und wird auf dem eigenen Rechner oder Server installiert. Über Microsoft 365 und Cloud-Dienste ist das Programm aber an die Außenwelt angebunden, daher der Namenszusatz Connected. Buchhaltung, Auftragsbearbeitung, Warenwirtschaft und Onlinebanking greifen ineinander, ohne dass Daten zwischen Programmen hin und her geschoben werden.</p><h3>Stärken</h3><p>Wer Waren einkauft, lagert und verkauft, bekommt hier eine echte Warenwirtschaft mit Beständen, Bestellwesen ab Comfort und Belegarchiv. Die Buchhaltung beherrscht EÜR und Bilanz, die DATEV-Schnittstelle und die E-Rechnung sind in allen Tarifen enthalten.</p><p>Ein Pluspunkt ist die Erweiterbarkeit. Onlineshop, Lohnabrechnung, Kasse oder Versand lassen sich zubuchen, wenn der Betrieb wächst. So muss nicht nach zwei Jahren das ganze System gewechselt werden.</p><h3>Schwächen</h3><p>Die Oberfläche ist funktional, aber weniger elegant als bei reinen Cloud-Programmen. Neue Anwender brauchen ein paar Tage Einarbeitung, dafür findet man später auch Funktionen, die anderswo fehlen. Wer ausschließlich im Browser arbeiten möchte, ist mit Sage Active besser bedient.</p><h3>Preise</h3><p>Standard kostet 30 € je Arbeitsplatz im Monat, Comfort 35 € ab zwei Arbeitsplätzen und Professional 40 € ab drei Arbeitsplätzen, jeweils netto. Alle Varianten lassen sich 30 Tage kostenlos testen, ohne dass Zahlungsdaten nötig sind. Für Handwerksbetriebe gibt es mit Sage 50 Handwerk eine eigene Branchenversion.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('BuchhaltungsButler', 'buchhaltungsbutler', 'Automatisierte Buchhaltung mit KI-gestützter Belegzuordnung', 'Buchhaltungssoftware aus Berlin, die Belege automatisch Kontobewegungen zuordnet und Buchungsvorschläge macht, mit DATEV-Export.', '<p>BuchhaltungsButler automatisiert die laufende Buchhaltung: Kontoumsätze werden abgerufen, Belege automatisch zugeordnet und Buchungen anhand gelernter Regeln vorgeschlagen. Das spart insbesondere bei vielen gleichartigen Belegen viel Zeit.</p><p>Die Software unterstützt SKR 03 und SKR 04, erzeugt Buchungsstapel im DATEV-Format und eignet sich sowohl für Unternehmen, die selbst buchen, als auch für die Zusammenarbeit mit der Steuerkanzlei.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 29.9, 'EUR', 'month', true, 'account', true, 14, false, false, '[{"name":"Light","price":29.9,"period":"month","unit":"account","features":["Sie buchen vor, die Kanzlei schließt ab","BWA, SuSa, Kontenblätter"]},{"name":"Smart","price":34.9,"period":"month","unit":"account","features":["Voller Funktionsumfang für EÜR und Bilanz","Automatische Buchungsvorschläge"],"highlighted":true},{"name":"Premium","price":59.9,"period":"month","unit":"account","features":["Alles aus Smart","Für bilanzierende Unternehmen mit hohem Belegvolumen"]}]'::jsonb, 'bei monatlicher Zahlung', '["Rechnungen & Angebote","Belegerfassung per OCR","Bankanbindung","UStVA per ELSTER","EÜR","Bilanz & GuV","DATEV-Export","Kassenbuch","Anlagenverwaltung"]'::jsonb, '["Automatische Belegzuordnung","Lernende Buchungsregeln","SKR 03 und SKR 04"]'::jsonb, '["DATEV","Amazon","PayPal","Stripe","Shopify"]'::jsonb, '["Hoher Automatisierungsgrad","Gute DATEV-Übergabe","Auch für Bilanzierer geeignet"]'::jsonb, '["Buchhalterisches Grundwissen nötig","Oberfläche wenig verspielt","Tarifgrenzen bei Belegmengen"]'::jsonb, 'Unternehmen mit vielen Belegen, die selbst vorkontieren.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, true, 'Deutschland', true, null, null, '["SKR03","SKR04"]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.buchhaltungsbutler.de/', 'keins', 'BuchhaltungsButler GmbH', null, 'Berlin', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.3, 4.1, 3.9, 4.3, 4.5, 'BuchhaltungsButler automatisiert die Belegzuordnung so konsequent wie kaum ein anderes Programm. Das hat seinen Preis: Mit 34,90 € im Monat für den Tarif Smart liegt es klar über Lexware Office und sevdesk.', '<h3>Was das Programm ausmacht</h3><p>Die Berliner Software setzt auf Automatisierung. Belege werden ausgelesen, mit den Kontobewegungen abgeglichen und mit einem Buchungsvorschlag versehen, der mit der Zeit immer besser wird. Wer viele wiederkehrende Buchungen hat, etwa im Onlinehandel, merkt das nach wenigen Wochen.</p><h3>Für E-Commerce besonders stark</h3><p>Anbindungen an Zahlungsdienste und Shopsysteme wie PayPal, Stripe und Shopify sind ein Schwerpunkt. Transaktionen werden automatisch zu Belegen und Buchungen, was bei hunderten kleinen Zahlungen im Monat viel Handarbeit erspart. Für Kanzleien gibt es eigene Tarife.</p><h3>Tarife und Kosten</h3><p>Light kostet 29,90 € im Monat und ist gedacht für die Arbeitsteilung, bei der Sie vorbuchen und die Kanzlei abschließt. Smart für 34,90 € bietet den vollen Funktionsumfang für EÜR und Bilanz, Premium für 59,90 € richtet sich an bilanzierende Unternehmen mit hohem Belegvolumen. Die Preise gelten bei monatlicher Zahlung, eine Testphase von 14 Tagen ist kostenlos.</p><p>Zusätzlich lassen sich Leistungen wie eine assistierte Buchhaltung oder ein manueller Belegreview hinzubuchen. Das ist praktisch, treibt die Kosten aber schnell nach oben.</p><h3>Unser Fazit</h3><p>BuchhaltungsButler ist keine Software für den Einzelunternehmer mit zehn Rechnungen im Monat. Für Betriebe mit vielen Transaktionen, besonders im Handel, rechnet sich der höhere Preis durch die eingesparte Zeit.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('FastBill', 'fastbill', 'Rechnungen schreiben und Belege erfassen', 'Rechnungsprogramm mit Belegerfassung, Bankabgleich und DATEV-Export für Selbstständige.', '<p>FastBill ist ein Rechnungsprogramm mit Belegerfassung aus Frankfurt am Main. Rechnungen, Angebote und wiederkehrende Abrechnungen lassen sich schnell erstellen; eingehende Belege werden automatisch ausgelesen und mit Kontoumsätzen abgeglichen.</p><p>Die Buchhaltung selbst übernimmt meist die Steuerkanzlei. FastBill liefert die vorbereiteten Daten per DATEV-Export.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 10, 'EUR', 'month', true, 'account', true, 14, false, false, '[{"name":"Solo","price":10,"period":"month","unit":"account","features":["1 Nutzer, 1 Bankkonto"]},{"name":"Plus","price":15,"period":"month","unit":"account","features":["5 Bankkonten","Unbegrenzte Vorlagen"],"highlighted":true},{"name":"Pro","price":30,"period":"month","unit":"account","features":["3 Nutzer, unbegrenzte Bankkonten","Wiederkehrende Rechnungen"]},{"name":"Premium","price":59,"period":"month","unit":"account","features":["5 Nutzer","Automatische Belegerfassung","Automatisches Mahnwesen"]}]'::jsonb, 'bei monatlicher Zahlung; jährlich ab 9 €', '["Rechnungen & Angebote","E-Rechnung (XRechnung/ZUGFeRD)","Belegerfassung per OCR","Bankanbindung","DATEV-Export","Mahnwesen","Mobile App"]'::jsonb, '["Wiederkehrende Rechnungen","Belegerfassung per App","DATEV-Export"]'::jsonb, '["DATEV","PayPal","Stripe","Zapier"]'::jsonb, '["Schnelle Rechnungserstellung","Günstiger Einstieg"]'::jsonb, '["Keine vollständige Buchhaltung","Kein direkter ELSTER-Versand"]'::jsonb, 'Selbstständige, die Rechnungen stellen und die Buchhaltung an die Kanzlei geben.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, false, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.fastbill.com/', 'keins', 'FastBill GmbH', null, 'Frankfurt am Main', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4, 4.2, 4, 3.9, 3.8, 'FastBill ist ein solides Rechnungsprogramm mit Belegerfassung, das vor allem Selbstständigen mit überschaubarem Belegaufkommen hilft. Die eigentliche Buchhaltung übernimmt in diesem Modell die Kanzlei.', '<h3>Das Konzept</h3><p>FastBill versteht sich als Vorbereitung für die Steuerkanzlei. Sie schreiben Rechnungen, verbinden das Bankkonto und sammeln Belege. Am Monatsende gehen die Daten per DATEV-Export an die Steuerberatung, die dort bucht und die Umsatzsteuer meldet.</p><h3>Tarife im Detail</h3><p>Solo kostet 10 € im Monat mit einem Nutzer und einem Bankkonto. Plus für 15 € erlaubt fünf Bankkonten und unbegrenzt eigene Vorlagen. Pro für 30 € bringt drei Nutzer und unbegrenzte Bankkonten, Premium für 59 € fünf Nutzer, automatische Belegerfassung und ein automatisches Mahnwesen. Bei jährlicher Zahlung sind alle Tarife etwas günstiger.</p><p>Auffällig ist, dass die automatische Belegerkennung erst im teuersten Tarif enthalten ist. Wer viele Belege hat, sollte das in die Rechnung einbeziehen.</p><h3>Stärken und Schwächen</h3><p>Der Rechnungsprozess ist übersichtlich, und die Zusammenarbeit mit der Kanzlei funktioniert reibungslos. Wer die Umsatzsteuer selbst melden möchte, ist bei Lexware Office oder sevdesk besser aufgehoben. Die 14 Tage kostenlose Testphase kommt ohne Abo und ohne Verpflichtung aus.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Papierkram', 'papierkram', 'Buchhaltung, Rechnungen und Zeiterfassung für Freiberufler', 'Buchhaltung für Freiberufler und Kleinunternehmen mit integrierter Projektzeiterfassung, inklusive kostenloser Version.', '<p>Papierkram kombiniert Rechnungsstellung, Buchhaltung und Projektzeiterfassung in einer Anwendung. Gerade Freiberufler, die nach Stunden abrechnen, profitieren davon, dass erfasste Zeiten direkt in Rechnungen übernommen werden.</p><p>EÜR und Umsatzsteuer-Voranmeldung sind enthalten; Kleinunternehmer nach § 19 UStG werden ausdrücklich unterstützt. Für einfache Anforderungen steht eine kostenlose Version zur Verfügung.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 0, 'EUR', 'month', true, 'account', false, null, true, false, '[{"name":"Free","price":0,"period":"month","unit":"account","features":["1 Nutzer, 100 MB","Rechnungen, Belege, Kontakte","Ohne Bankanbindung und Steuerberichte"]},{"name":"S","price":12.9,"period":"month","unit":"account","features":["Bankabgleich für 2 Konten","Zeiterfassung","1.000 MB Speicher"]},{"name":"M","price":24.9,"period":"month","unit":"account","features":["Unbegrenzte Nutzer","EÜR, UStVA und BWA","Team-Zeiterfassung, Kundenportal"],"highlighted":true},{"name":"L","price":49.9,"period":"month","unit":"account","features":["Alles aus M","REST-API","Unbegrenzte Bankkonten"]}]'::jsonb, 'bei monatlicher Zahlung; jährlich ab 9,90 €', '["Rechnungen & Angebote","Belegerfassung per OCR","Bankanbindung","UStVA per ELSTER","EÜR","DATEV-Export","Mahnwesen"]'::jsonb, '["Projektzeiterfassung integriert","Kleinunternehmerregelung (§ 19 UStG)","Kostenlose Version"]'::jsonb, '["DATEV","PayPal","Stripe"]'::jsonb, '["Ideal für Stundenabrechnung","Faire Preise","Kostenlose Einstiegsversion"]'::jsonb, '["Nicht für Bilanzierer","Weniger Automatisierung als größere Anbieter"]'::jsonb, 'Freiberufler und Kleinunternehmer mit Stundenabrechnung.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, true, 'Deutschland', true, null, null, '["SKR03","SKR04"]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.papierkram.de/', 'keins', 'Papierkram GmbH', null, 'Osnabrück', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.3, 4.4, 4.5, 4.2, 4, 'Papierkram verbindet Buchhaltung, Rechnungen, Projekte und Zeiterfassung zu einem fairen Preis. Für Freiberufler und kleine Agenturen, die nach Stunden abrechnen, ist das eine der stimmigsten Lösungen am Markt.', '<h3>Das Besondere</h3><p>Papierkram kombiniert zwei Welten, die sonst getrennt sind: Buchhaltung und Projektarbeit. Sie erfassen Zeiten auf Projekte, rechnen sie ab und sehen im selben Programm, wie sich das auf Umsatz und Steuer auswirkt. Für Grafikbüros, Beratungen und Entwickler ist das sehr praktisch.</p><h3>Tarife</h3><p>Die kostenlose Version eignet sich für den Einstieg mit einem Nutzer, bietet aber weder Bankanbindung noch Steuerberichte. S für 12,90 € im Monat bringt die Bankanbindung für zwei Konten und die Zeiterfassung. M für 24,90 € ist der eigentliche Standard: unbegrenzte Nutzer, EÜR, Umsatzsteuer-Voranmeldung, BWA, Team-Zeiterfassung und ein Kundenportal. L für 49,90 € ergänzt eine REST-API und unbegrenzt viele Bankkonten.</p><p>Bei jährlicher Zahlung sinken die Preise auf 9,90 €, 19,90 € und 39,90 €. Alle Preise sind netto.</p><h3>Im Alltag</h3><p>Die Oberfläche ist aufgeräumt und schnell. Der Wechsel zwischen Zeiterfassung, Rechnung und Buchhaltung gelingt ohne Umwege. Eine klassische Testphase gibt es nicht, die kostenlose Version übernimmt diese Rolle.</p><h3>Für wen es passt</h3><p>Papierkram lohnt sich für alle, die projektbasiert arbeiten und ihre Buchhaltung selbst führen. Für Onlinehändler mit hohem Transaktionsvolumen ist BuchhaltungsButler die bessere Wahl.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false)
